check(parse_capture(json_value($f))['candidates'][0]['account']===$expected['account'],'encrypted JSON envelope');check(parse_capture(json_value($outer))['candidates'][0]['source']==='plaintext','decrypted outer JSON with nested string');$obj=$outer;$obj['param']=json_decode($obj['param'],true);check(parse_capture(json_value($obj))['candidates'][0]['roomverify']===$expected['roomverify'],'decrypted nested object');
